/**
 * Notification Types
 *
 * Notifications are generated by formula fields (code fields, sum fields)
 * to communicate issues or insights about extracted data.
 *
 * @module Notification
 */

// ═══════════════════════════════════════════════════════════════════════════════
// NOTIFICATION STATUS
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Notification status values.
 * - NEW: Just created, not yet reviewed (shows badge in UI)
 * - PENDING: Acknowledged but not resolved
 * - RESOLVED: Issue has been fixed
 * - IGNORED: User chose to ignore this notification
 */
export const NOTIFICATION_STATUSES = [
  "NEW",
  "PENDING",
  "RESOLVED",
  "IGNORED",
] as const;
export type NotificationStatus = (typeof NOTIFICATION_STATUSES)[number];

// ═══════════════════════════════════════════════════════════════════════════════
// NOTIFICATION LEVEL
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Notification level/severity.
 * - info: Informational note (not persisted to table)
 * - warning: Data quality issue (persisted to table)
 * - error: Critical problem (persisted to table)
 */
export const NOTIFICATION_LEVELS = ["info", "warning", "error"] as const;
export type NotificationLevel = (typeof NOTIFICATION_LEVELS)[number];

// ═══════════════════════════════════════════════════════════════════════════════
// NOTIFICATION TYPE
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Notification type/scope.
 * - DOCUMENT: Notification related to a specific document (from formula evaluation)
 * - TASK: Notification from a scheduled task (org-scoped)
 */
export const NOTIFICATION_TYPES = ["DOCUMENT", "TASK"] as const;
export type NotificationType = (typeof NOTIFICATION_TYPES)[number];

// ═══════════════════════════════════════════════════════════════════════════════
// NOTIFICATION INTERFACES
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Notification as stored in document_data.notifications JSONB column.
 *
 * For warning/error: includes `id` referencing the notifications table
 * For info: no `id`, not persisted to notifications table
 */
export interface DocumentNotification {
  /** Only set for warning/error (references notifications table) */
  id?: string;

  /** Notification level */
  level: NotificationLevel;

  /** Human-readable message */
  message: string;

  /** Path to the field this notification relates to, e.g., "header.total", "items[2].amount" */
  fieldPath?: string;

  /** Name of the formula field that generated this notification */
  formulaField?: string;
}

/**
 * Full notification record from notifications table.
 * Only warning/error notifications are persisted here.
 */
export interface NotificationRecord {
  /** Primary key */
  id: string;

  /** Organization ID */
  orgId: string;

  /** Document ID (null for task-scoped notifications) */
  documentId: string | null;

  /** Notification type/scope */
  notificationType: NotificationType;

  /** Metadata for flexible linking (e.g., taskId for TASK notifications) */
  metadata: Record<string, unknown> | null;

  /** Notification level */
  level: NotificationLevel;

  /** Human-readable message */
  message: string;

  /** Path to the field this notification relates to */
  fieldPath: string | null;

  /** Name of the formula field that generated this notification */
  formulaField: string | null;

  /** Current status */
  status: NotificationStatus;

  /** When notification was created */
  createdAt: Date;
}

